UPDATE `item_sparse_locale` l JOIN `item_sparse` b ON b.ID=l.ID SET l.`Display_lang`='Ветвь древнего' WHERE l.ID=233250 AND l.locale='ruRU' AND b.VerifiedBuild=COALESCE((SELECT MAX(v.VerifiedBuild) FROM `item_sparse` v WHERE v.ID=b.ID AND v.VerifiedBuild<=0),(SELECT MAX(v.VerifiedBuild) FROM `item_sparse` v WHERE v.ID=b.ID AND v.VerifiedBuild>0)) AND MD5(b.`Display`)='aef30283da98f6a6b1a0aa460a6570da' AND COALESCE(l.`Display_lang`,'')='';
INSERT INTO hotfix_data (Id,UniqueId,TableHash,RecordId,Status,VerifiedBuild) SELECT 4050007,22,2442913102,233250,1,0 FROM DUAL WHERE EXISTS (SELECT 1 FROM `item_sparse` WHERE ID=233250) AND EXISTS (SELECT 1 FROM `item_sparse_locale` WHERE ID=233250 AND locale='ruRU') ON DUPLICATE KEY UPDATE Status=VALUES(Status);
COMMIT;
